import React from 'react';
import ClinicRow from './ClinicRow';
import { Clinic } from '../types/clinic';
import './ClinicTable.css';

const clinicsData: Clinic[] = [
    {
        name: 'Clínica Estética Garanhuns',
        address: 'Rua das Flores, 123 - Centro, Garanhuns - PE',
        instagram: 'https://instagram.com/clinicaesteticagaranhuns'
    },
    {
        name: 'Harmoniza Garanhuns',
        address: 'Avenida Rui Barbosa, 456 - Heliópolis, Garanhuns - PE',
        instagram: 'https://instagram.com/harmonizagaranhuns'
    },
    {
        name: 'Beleza Facial Garanhuns',
        address: 'Praça da Bandeira, 789 - São José, Garanhuns - PE',
        instagram: 'https://instagram.com/beleza_facial_garanhuns'
    },
    {
        name: 'Estética e Saúde Garanhuns',
        address: 'Rua do Comércio, 321 - Boa Vista, Garanhuns - PE',
        instagram: 'https://instagram.com/esteticaesaudegaranhuns'
    },
];

const ClinicTable: React.FC = () => {
    return (
        <div className="clinic-table">
            <h2>Clínicas de Harmonização Facial em Garanhuns</h2>
            <table>
                <thead>
                    <tr>
                        <th>Nome da Clínica</th>
                        <th>Endereço</th>
                        <th>Instagram</th>
                    </tr>
                </thead>
                <tbody>
                    {clinicsData.map((clinic, index) => (
                        <ClinicRow key={index} clinic={clinic} />
                    ))}
                </tbody>
            </table>
        </div>
    );
};

export default ClinicTable;
